#!/bin/bash
# Ensaya la migración 0009 (integridad de identificadores) en una copia desechable CON DATOS reales de las tablas afectadas (esquema "ensayo", sin llaves foráneas).
# Uso: bash ensayar_0009.sh   (desde backend/, con el túnel a producción abierto). Al final deja el esquema para inspección; se borra con borrar.sh.
cd "$(dirname "$0")/../../.." || exit 1
S="ssh -p 2223 -i $HOME/.ssh/jesus.rios.pem -o HostKeyAlias=simac-produccion jesus.rios@localhost"
F=db/migrations/0009_integridad_de_identificadores.sql
awk '/^-- Down Migration/{exit} {print}' $F | $S 'cat > /tmp/up0009.sql'
awk 'f{print} /^-- Down Migration/{f=1}' $F | $S 'cat > /tmp/down0009.sql'
$S 'cd /var/www/Simulador/backend && set -a && . ./.env && set +a && export PGPASSWORD=$DB_PASSWORD && PS="psql -h $DB_HOST -p ${DB_PORT:-5432} -U $DB_USER $DB_NAME -v ON_ERROR_STOP=1 -q" &&
pg_dump -s -n public --no-owner --no-privileges -h $DB_HOST -p ${DB_PORT:-5432} -U $DB_USER $DB_NAME -f /tmp/esquema_public.sql &&
grep -v -E "^(CREATE EXTENSION|COMMENT ON EXTENSION|CREATE SCHEMA|COMMENT ON SCHEMA)" /tmp/esquema_public.sql | perl -pe "s/\bpublic\.(?!geometry|geography|spatial_ref_sys|box2d|box3d|st_|_st_|postgis|gidx|pgis|geometry_dump|valid_detail)/ensayo./g" > /tmp/esquema_ensayo.sql &&
$PS -c "DROP SCHEMA IF EXISTS ensayo CASCADE" -c "CREATE SCHEMA ensayo" 2>/dev/null; $PS --single-transaction -c "SET search_path=ensayo,public" -f /tmp/esquema_ensayo.sql >/dev/null 2>&1;
for c in $($PS -At -c "select k.relname||\$\$:\$\$||c.conname from pg_constraint c join pg_class k on k.oid=c.conrelid where c.contype=\$\$f\$\$ and k.relnamespace=\$\$ensayo\$\$::regnamespace"); do $PS -c "ALTER TABLE ensayo.${c%%:*} DROP CONSTRAINT ${c##*:}"; done;
for t in ciclo ciclo_cultivo alertas cosecha_real disponibilidad_productor estimacion_cosecha precios seguimiento_incidencias seguimiento_visitas senales_compra senal_interesados senal_variedades notificaciones transacciones bodeguero_bodegas cat_catalogo cat_programas_gobierno inventarios tarifario_servicios precio_referencias_externas alertas_up productor_perfil geo_estado apoyos_ventanilla cat_conceptos_servicio cat_variedad_cultivo costos_fira discrepancias infraestructura_contactos oferta_interes precio_parametros precios_maiz regiones senasica_cargas senasica_parametros sesiones solicitudes_apoyo supervisor_productores ventanillas; do $PS -c "INSERT INTO ensayo.$t SELECT * FROM public.$t"; done;
for s in $($PS -At -c "select relname from pg_class where relkind=\$\$S\$\$ and relnamespace=\$\$ensayo\$\$::regnamespace"); do v=$($PS -At -c "select last_value from public.$s" 2>/dev/null); [ -n "$v" ] && $PS -At -c "select setval(\$\$ensayo.$s\$\$, $v)" >/dev/null; done;
echo "== antes"; $PS -At -F"|" -c "set search_path=ensayo,public; select \$\$ciclo\$\$, count(*), count(distinct ciclo_id) from ciclo union all select \$\$precios\$\$, count(*), count(distinct id) from precios union all select \$\$notificaciones\$\$, count(*), count(distinct id) from notificaciones union all select \$\$senales_compra\$\$, count(*), count(distinct id) from senales_compra union all select \$\$transacciones\$\$, count(*), count(distinct id) from transacciones";
echo "== up"; $PS --single-transaction -c "SET search_path=ensayo,public" -f /tmp/up0009.sql 2>&1 | tail -5;
echo "== despues"; $PS -At -F"|" -c "set search_path=ensayo,public; select \$\$ciclo\$\$, count(*), count(distinct ciclo_id) from ciclo union all select \$\$precios\$\$, count(*), count(distinct id) from precios union all select \$\$notificaciones\$\$, count(*), count(distinct id) from notificaciones union all select \$\$senales_compra\$\$, count(*), count(distinct id) from senales_compra union all select \$\$transacciones\$\$, count(*), count(distinct id) from transacciones union all select \$\$correcciones\$\$, count(*), 0 from correcciones_identificadores union all select \$\$tablas_sin_pk\$\$, count(*), 0 from pg_class c where relnamespace=\$\$ensayo\$\$::regnamespace and relkind=\$\$r\$\$ and not exists (select 1 from pg_constraint k where k.conrelid=c.oid and k.contype=\$\$p\$\$)"'
